$server->exec("DROP DATABASE IF EXISTS `$name`");$server->exec("CREATE DATABASE `$name` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");$cfg['db_name']=$name;Db::connect($cfg);
