$pass=0;$fail=0;
function ws_ok(bool $value,string $message):void{if(!$value)throw new RuntimeException($message);}
function ws_reject(callable $fn,string $text):void{try{$fn();}catch(AppError|Forbidden $e){ws_ok(stripos($e->getMessage(),$text)!==false,'Wrong error: '.$e->getMessage());return;}throw new RuntimeException('Expected rejection: '.$text);}
function ws_test(string $name,callable $fn):void{global $pass,$fail;try{$fn();$pass++;echo "PASS $name\n";}catch(Throwable $e){$fail++;echo "FAIL $name: ".$e->getMessage()."\n";}}
function ws_admin():void{Auth::actAs((int)Db::val("SELECT id FROM sis_users WHERE username='admin'"));}
ws_admin();Db::q("UPDATE sis_users SET password_hash=?,must_change_password=0 WHERE username='admin'",[password_hash('Testing12345',PASSWORD_DEFAULT)]);
$cashier=Db::insert('sis_users',['username'=>'ws_cashier','full_name'=>'Test Cashier','role'=>'CASHIER','password_hash'=>password_hash('Testing12345',PASSWORD_DEFAULT)]);
$old=GS::saveSection(null,'2025-2026','1st Year','WS 1A');$new=GS::saveSection(null,'2026-2027','2nd Year','WS 2A');$sub=GS::saveSubject(null,'WS101','Workspace subject','3');
$cat=Assessment::saveCategory(null,['name'=>'Workspace tuition','is_active'=>1]);$label=Assessment::saveLabel(null,['name'=>'Workspace fee','category_id'=>$cat,'charge_type'=>'FIXED','default_amount'=>'1000','is_active'=>1]);$fee=Assessment::saveName(null,['name'=>'Workspace assessment','is_active'=>1]);Assessment::setItem($fee,$label,'FIXED',100000);
function ws_student(string $number,string $name):array{global $old,$fee,$sub;ws_admin();$id=GS::saveStudent(null,['studentId'=>$number,'studentName'=>$name,'sectionId'=>$old]);[$rid]=Registration::create(null,$number,$old,'2nd Semester',$fee,[$sub]);return ['student'=>GS::get('students',$id),'registration'=>$rid];}
