Cashier::pay($a['registration'],20000,'CASH',null,bin2hex(random_bytes(16)),null);
$caseA=BalanceEnrollment::request('WS001','2026-2027','1st Semester','ARRANGEMENT',20000,'Requesting a payment arrangement.');
$caseB=BalanceEnrollment::request('WS002','2026-2027','1st Semester','SPECIAL',0,'Special financial approval requested.');BalanceEnrollment::decide($caseB,'APPROVED','Reviewed by Accounting.','PENDING');
$caseD=BalanceEnrollment::request('WS004','2026-2027','1st Semester','SPECIAL',0,'Request before settlement.');BalanceEnrollment::decide($caseD,'APPROVED','Financial review completed.','PENDING');Cashier::pay($d['registration'],100000,'CASH',null,bin2hex(random_bytes(16)),null);
ws_test('summary reconciles prior balances, including students without requests',function(){ $r=BalanceWorkspace::directory('2026-2027','1st Semester');ws_ok($r['total_balance']===280000,'Wrong balance total');ws_ok($r['students']===3&&$r['pending']===1&&$r['approved']===2,'Wrong summary counts');ws_ok(count($r['rows'])===4,'No-request or settled-request student omitted');});
ws_test('payment status and approval status are independent',function(){ $rows=array_column(BalanceWorkspace::directory('2026-2027','1st Semester')['rows'],null,'number');ws_ok($rows['WS002']['payment_state']==='UNPAID'&&$rows['WS002']['request_state']==='APPROVED','Approval falsely settled balance');ws_ok($rows['WS001']['payment_state']==='PARTIAL','Partial payment missing');ws_ok($rows['WS004']['payment_state']==='SETTLED','Settlement missing'); });
ws_test('name, student ID and independent status filters work',function(){ $r=BalanceWorkspace::directory('2026-2027','1st Semester')['rows'];ws_ok(count(BalanceWorkspace::filterRows($r,'juan','ALL','ALL'))===1,'Name search');ws_ok(count(BalanceWorkspace::filterRows($r,'WS003','NONE','UNPAID'))===1,'No-request filter');ws_ok(count(BalanceWorkspace::filterRows($r,'','APPROVED','UNPAID'))===1,'Independent filters'); });
ws_test('directory and original balance service agree for each student',function(){foreach(BalanceWorkspace::directory('2026-2027','1st Semester')['rows'] as $r)ws_ok($r['balance']===BalanceEnrollment::outstanding($r['number'],'2026-2027','1st Semester')['cents'],'Balance mismatch '.$r['number']);});
ws_test('current and future terms and voided records do not become previous balance',function()use($new,$fee,$sub){$x=GS::saveStudent(null,['studentId'=>'WSFUTURE','studentName'=>'Future, Check','sectionId'=>$new]);[$rid]=Registration::create(null,'WSFUTURE',$new,'2nd Semester',$fee,[$sub]);$r=BalanceWorkspace::directory('2026-2027','1st Semester');ws_ok(!in_array('WSFUTURE',array_column($r['rows'],'number'),true),'Future term included');Registration::void($rid,'Test void');ws_ok(!BalanceWorkspace::priorRegistrations('WSFUTURE','2027-2028','1st Semester'),'Voided record included');});
$filters=['tab'=>'all','event'=>'ALL','q'=>'','after'=>'','before'=>'','page'=>1];
ws_test('notification inbox is recipient-scoped',function()use($cashier,$filters){$private=Db::insert('sis_notifications',['recipient_user_id'=>$cashier,'type'=>'OTHER','title'=>'Private cashier item','message'=>'Not for the admin']);ws_ok(NotificationCenter::findCurrent($private)===null,'Private notification exposed');NotificationCenter::markRead($private);ws_ok(!(int)Db::val('SELECT is_read FROM sis_notifications WHERE id=?',[$private]),'Other recipient read state changed');$r=NotificationCenter::inbox(array_replace($filters,['q'=>'Private cashier']));ws_ok($r['total']===0,'Search leaked another inbox');});
ws_test('read and mark-all-read do not decide requests',function()use($caseA,$filters){$n=Db::one("SELECT * FROM sis_notifications WHERE recipient_role='ADMIN' AND entity_id=? ORDER BY id LIMIT 1",[(string)$caseA]);NotificationCenter::markRead((int)$n['id']);ws_ok(BalanceWorkspace::case($caseA)['status']==='PENDING','Read approved request');NotificationCenter::markAllRead();ws_ok(NotificationCenter::unreadCount()===0,'Mark-all failed');ws_ok(BalanceWorkspace::case($caseA)['status']==='PENDING','Mark-all decided request');});
ws_test('Needs my action uses current status and reviewer permissions',function()use($filters,$cashier){$r=NotificationCenter::inbox(array_replace($filters,['tab'=>'action']));ws_ok($r['total']===1,'Pending request absent');Auth::actAs($cashier);$r=NotificationCenter::inbox(array_replace($filters,['tab'=>'action']));ws_ok($r['total']===0,'Cashier offered pending approval');ws_admin();});
ws_test('stale review cannot revoke another reviewers new approval',function()use($caseA){BalanceEnrollment::decide($caseA,'APPROVED','First reviewer approved.','PENDING');ws_reject(fn()=>BalanceEnrollment::decide($caseA,'REJECTED','Stale pending review.','PENDING'),'changed while');ws_ok(BalanceWorkspace::case($caseA)['status']==='APPROVED','Stale form revoked approval');});
ws_test('resolved requested notification no longer needs action; explicit revoke still works',function()use($caseA,$filters){ws_ok(NotificationCenter::inbox(array_replace($filters,['tab'=>'action']))['total']===0,'Resolved request still actionable');BalanceEnrollment::decide($caseA,'REJECTED','Approval explicitly revoked.','APPROVED');$n=Db::one("SELECT id FROM sis_notifications WHERE recipient_role='ADMIN' AND type='BALANCE_REVOKED' ORDER BY id DESC LIMIT 1");ws_ok($n!==null,'Revocation event missing');ws_ok(NotificationCenter::findCurrent((int)$n['id'])['event']==='REVOKED','Revocation mislabeled');});
ws_test('legacy notifications remain filterable',function()use($filters){Db::insert('sis_notifications',['recipient_role'=>'ADMIN','type'=>'BALANCE_CASE','title'=>'Payment arrangement request needs review','message'=>'Legacy event','entity_type'=>'balance_case','entity_id'=>'99999']);$r=NotificationCenter::inbox(array_replace($filters,['q'=>'Legacy event','event'=>'REQUESTED']));ws_ok($r['total']===1,'Legacy request lost');});
ws_test('date filters, pagination and unread filter have accurate totals',function()use($filters){for($i=0;$i<27;$i++)Db::insert('sis_notifications',['recipient_role'=>'ADMIN','type'=>'OTHER','title'=>'Paged notice '.$i,'message'=>'pagination fixture','created_at'=>'2026-01-02 12:00:00']);$f=array_replace($filters,['q'=>'pagination fixture','after'=>'2026-01-02','before'=>'2026-01-02','tab'=>'unread']);$r=NotificationCenter::inbox($f);ws_ok($r['total']===27&&count($r['rows'])===20&&$r['pages']===2,'First page count incorrect');$r=NotificationCenter::inbox(array_replace($f,['page'=>2]));ws_ok(count($r['rows'])===7,'Second page incorrect');ws_ok(NotificationCenter::inbox(array_replace($f,['before'=>'2026-01-01']))['total']===0,'Date constraint ignored');});
ws_test('cashier cannot approve a pending request but can deliberately revoke an approved one',function()use($cashier,$caseB){$case=BalanceEnrollment::request('WS003','2026-2027','1st Semester','ARRANGEMENT',0,'Permission test request.');Auth::actAs($cashier);ws_reject(fn()=>BalanceEnrollment::decide($case,'APPROVED','Cashier attempted review.','PENDING'),'cannot approve');BalanceEnrollment::decide($caseB,'REJECTED','Authorized revocation.','APPROVED');ws_admin();});
